from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or \
       not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def get_neighbors(r, c):
        return [(r+dr, c+dc) for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)] if is_valid(r+dr, c+dc)]

    visited_forward = {start: [start]}
    visited_backward = {goal: [goal]}
    forward = deque([start])
    backward = deque([goal])

    while forward and backward:
        # Expand forward
        if len(forward) <= len(backward):
            current = forward.popleft()
            for neighbor in get_neighbors(current[0], current[1]):
                if neighbor not in visited_forward:
                    visited_forward[neighbor] = visited_forward[current] + [neighbor]
                    if neighbor in visited_backward:
                        return visited_forward[neighbor] + visited_backward[neighbor][::-1][1:]
                    forward.append(neighbor)
        else:
            current = backward.popleft()
