from collections import deque

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []

    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if (start_row < 0 or start_row >= rows or start_col < 0 or start_col >= cols or
        grid[start_row][start_col] == '#' or
        grid[goal_row][goal_col] == '#'):
        return []

    if start == goal:
        return [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(from_queue, from_parent, to_queue, to_parent):
        while from_queue:
            r, c = from_queue.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#' and (nr, nc) not in from_parent:
                    if (nr, nc) in to_parent:
                        path = []
                        path.append((nr, nc))
                        curr = (nr, nc)
                        while curr != from_queue[0]:
                            curr = from_parent[curr]
                            path.append(curr)
                        path.append(from_queue[0])
                        return path
                    from_parent[(nr, nc)] = (r, c)
                    from_queue.append((nr, nc))
        return None

    # Bidirectional BFS
    from_queue = deque([start])
    from_parent = {start: None}
    to_queue = deque([goal])
    to_parent = {goal: None}

    while from_queue and to_queue:
        result = bfs(from_queue, from_parent, to_queue, to_parent)
        if result:
            return result
        result = bfs(to_queue, to_parent, from_queue, from_parent)
        if result:
            return result

    return []

