    def bfs(start, goal, visited, path):
        queue = deque()
        queue.append((start[0], start[1], [start]))
        visited.add((start[0], start[1]))

        while queue:
            r, c, path = queue.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                    if (nr, nc) == goal:
                        return path + [(nr, nc)]
                    visited.add((nr, nc))
                    queue.append((nr, nc, path + [(nr, nc)]))
        return []

    visited_forward = set()
    visited_backward = set()
    path_forward = []
    path_backward = []

    forward_queue = deque()
    forward_queue.append((start[0], start[1], [start]))
    visited_forward.add((start[0], start[1]))

    backward_queue = deque()
    backward_queue.append((goal[0], goal[1], [goal]))
    visited_backward.add((goal[0], goal[1]))

    while forward_queue and backward_queue:
        # Expand forward
        r, c, path = forward_queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited_forward:
                visited_forward.add((nr, nc))
                forward_queue.append((nr, nc, path + [(nr, nc)]))
                if (nr, nc) in visited_backward:
                    return path + [(nr, nc)] + path_backward[::-1][1:]

