        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited_backward:
                visited_backward.add((nr, nc))
                backward_queue.append((nr, nc, path + [(nr, nc)]))
