import heapq

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if (start_row < 0 or start_row >= rows or
        start_col < 0 or start_col >= cols or
        grid[start_row][start_col] == '#' or
        grid[goal_row][goal_col] == '#'):
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    visited = set()
    priority_queue = [(heuristic(start, goal), 0, start, [start])]

    while priority_queue:
        _, cost, current, path = heapq.heappop(priority_queue)
        current_row, current_col = current

        if current == goal:
            return path

        if current in visited:
            continue
        visited.add(current)

        for dr, dc in directions:
            nr, nc = current_row + dr, current_col + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                new_path = path + [(nr, nc)]
                heapq.heappush(priority_queue, (cost + 1 + heuristic((nr, nc), goal), cost + 1, (nr, nc), new_path))

    return []

