    if not grid or not grid[0]:
        return []
    if start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []
    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    heap = [(0, start[0], start[1])]
    came_from = {}

    while heap:
        _, r, c = heapq.heappop(heap)
        if (r, c) == goal:
            break
        if (r, c) in visited:
            continue
        visited.add((r, c))
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                heapq.heappush(heap, (1, nr, nc))
                came_from[(nr, nc)] = (r, c)

    if (goal[0], goal[1]) not in came_from:
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        current = came_from[current]
    path.append(start)
    return path[::-1]

