from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # SPFA (Shortest Path Faster Algorithm)
    dist = [float('inf')] * n
    dist[s] = 0
    in_queue = [False] * n
    queue = deque()
    queue.append(s)
