        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dial's bucket-queue algorithm
    # Each bucket is a list of nodes with a certain distance
    # We use a dictionary to map distance values to lists of nodes
    buckets = {}
    dist = [-1] * n
    dist[s] = 0
    buckets[0] = [s]

    while buckets:
        # Find the smallest distance in the buckets
        min_dist = min(buckets.keys())
        bucket = buckets[min_dist]

        # Process each node in the current bucket
        for u in bucket:
            for v, w in adj[u]:
                if dist[v] == -1 or dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    if dist[v] not in buckets:
                        buckets[dist[v]] = []
                    buckets[dist[v]].append(v)

        # Remove the processed bucket
        del buckets[min_dist]

    return dist[t] if dist[t] != -1 else -1

