from collections import deque

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    if start[0] < 0 or start[0] >= rows or start[1] < 0 or start[1] >= cols or grid[start[0]][start[1]] == '#':
        return []
    if goal[0] < 0 or goal[0] >= rows or goal[1] < 0 or goal[1] >= cols or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    def bfs_from(start, direction):
        visited = set()
        queue = deque([(start, [start])])
        visited.add(start)
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        while queue:
            (r, c), path = queue.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                    if (nr, nc) == goal:
                        return path + [(nr, nc)]
                    visited.add((nr, nc))
                    queue.append(((nr, nc), path + [(nr, nc)]))
        return None

    forward_path = bfs_from(start, 'forward')
    backward_path = bfs_from(goal, 'backward')

    if not forward_path or not backward_path:
        return []

    forward_set = set(forward_path)
    backward_set = set(backward_path)

    for node in forward_path:
        if node in backward_set:
            idx = forward_path.index(node)
            return forward_path[:idx+1] + backward_path[::-1][idx+1:]

    return []

