from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) or
            0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    visited_forward = set()
    visited_backward = set()
    queue_forward = deque([(start, [start])])
    queue_backward = deque([(goal, [goal])])
    visited_forward.add(start)
    visited_backward.add(goal)

    while queue_forward and queue_backward:
        # Expand forward direction
        if queue_forward:
            curr, path = queue_forward.popleft()
            for neighbor in get_neighbors(curr[0], curr[1]):
                if neighbor not in visited_forward:
                    visited_forward.add(neighbor)
                    new_path = path + [neighbor]
                    if neighbor in visited_backward:
                        return new_path[:new_path.index(neighbor) + 1] + new_path[new_path.index(neighbor):][::-1]
                    queue_forward.append((neighbor, new_path))

        # Expand backward direction
        if queue_backward:
            curr, path = queue_backward.popleft()
            for neighbor in get_neighbors(curr[0], curr[1]):
                if neighbor not in visited_backward:
