        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    forward = {start: [start]}
    backward = {goal: [goal]}
    visited_forward = {start}
    visited_backward = {goal}

    while forward and backward:
        if len(forward) <= len(backward):
            current = forward
            other = backward
            visited = visited_forward
        else:
            current = backward
            other = forward
            visited = visited_backward

        next_nodes = {}
        for node in current:
            for neighbor in get_neighbors(*node):
                if neighbor not in visited:
                    path = current[node] + [neighbor]
                    next_nodes[neighbor] = path
                    visited.add(neighbor)

        if next_nodes:
            for node in next_nodes:
                if node in other:
                    return next_nodes[node] + other[node][::-1][1:]
            forward.update(next_nodes)
        else:
            break

