        grid[start_row][start_col] == '#' or
        grid[goal_row][goal_col] == '#'):
        return []

    if start == goal:
        return [start]

    def bfs(frontier, came_from, target_row, target_col):
        while frontier:
            r, c = frontier.popleft()
            if r == target_row and c == target_col:
