import heapq

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Check if start or goal is out of bounds or a wall
    if not (0 <= start[0] < rows and 0 <= start[1] < cols):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # If start is the same as goal
    if start == goal:
        return [start]

    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    # Priority queue for Dijkstra's algorithm (using unit weight)
    priority_queue = [(0, start[0], start[1])]
    visited = set()
    parent = {}

    while priority_queue:
        _, r, c = heapq.heappop(priority_queue)
        if (r, c) == goal:
            break
        if (r, c) in visited:
            continue
        visited.add((r, c))
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#' and (nr, nc) not in visited:
                heapq.heappush(priority_queue, (1, nr, nc))
                parent[(nr, nc)] = (r, c)

    # Reconstruct path
    path = []
    current = goal
    while current in parent:
        path.append(current)
        current = parent[current]
    if current == start:
        path.append(start)
        path.reverse()
    else:
        return []

    return path

