import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bidirectional Dijkstra's algorithm
    def dijkstra(start, target):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        prev = [None] * n

        while heap:
            current_dist, u = heapq.heappop(heap)
            if u == target:
                break
            if current_dist > dist[u]:
                continue
            for v, weight in adj[u]:
                if dist[v] > dist[u] + weight:
                    dist[v] = dist[u] + weight
                    prev[v] = u
                    heapq.heappush(heap, (dist[v], v))
        return dist, prev

    # Run Dijkstra from both ends
    dist_s, _ = dijkstra(s, t)
    dist_t, _ = dijkstra(t, s)

    # Try to find a common node with minimal total distance
    min_dist = float('inf')
    for i in range(n):
        if dist_s[i] != float('inf') and dist_t[i] != float('inf'):
            min_dist = min(min_dist, dist_s[i] + dist_t[i])

    return min_dist if min_dist != float('inf') else -1

