import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bidirectional Dijkstra's algorithm
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        came_from = {}

        while heap:
            current_dist, u = heapq.heappop(heap)
            if u == end:
                break
            if current_dist > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(heap, (dist[v], v))
                    came_from[v] = u
        return dist, came_from

    # Run Dijkstra from both ends
    dist_s, came_from_s = dijkstra(s, t)
    dist_t, came_from_t = dijkstra(t, s)

    # Find the meeting point
    meeting_point = None
    for i in range(n):
        if dist_s[i] + dist_t[i] < float('inf'):
            meeting_point = i
            break

    if meeting_point is None:
        return -1

    # Reconstruct the shortest path from s to t using both came_from dictionaries
    path_s = {}
    u = meeting_point
    while u in came_from_s:
        path_s[u] = came_from_s[u]
        u = came_from_s[u]

    path_t = {}
    u = meeting_point
    while u in came_from_t:
        path_t[u] = came_from_t[u]
        u = came_from_t[u]

    # Combine paths
    full_path = {}
    u = t
    while u in path_t:
        full_path[u] = path_t[u]
        u = path_t[u]

    u = s
    while u in path_s:
        full_path[u] = path_s[u]
        u = path_s[u]

    # Calculate total weight
    total_weight = 0
    for i in range(len(full_path) - 1):
        u = list(full_path.keys())[i]
        v = list(full_path.values())[i]
        # Find the edge weight from u to v
        for edge in edges:
            if edge[0] == u and edge[1] == v:
                total_weight += edge[2]
                break

    return total_weight

