    def dijkstra(start, target):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        came_from = {}
        while heap:
            current_dist, u = heapq.heappop(heap)
            if u == target:
                break
            if current_dist > dist[u]:
                continue
            for v, weight in adj[u]:
                if dist[v] > dist[u] + weight:
                    dist[v] = dist[u] + weight
                    heapq.heappush(heap, (dist[v], v))
                    came_from[v] = u
        return dist, came_from

    # Run Dijkstra from both ends
    dist_s, came_from_s = dijkstra(s, t)
    dist_t, came_from_t = dijkstra(t, s)

    # Check if t is reachable from s
    if dist_s[t] == float('inf'):
        return -1

    # Reconstruct the path and find the meeting point
    path_s = set()
    path_t = set()
    u = t
    while u in came_from_s:
        path_s.add(u)
        u = came_from_s[u]
    u = s
    while u in came_from_t:
        path_t.add(u)
        u = came_from_t[u]

