            # Reconstruct path from s to i and from t to i
            path_s = []
            curr = i
            while curr != -1:
                path_s.append(curr)
                curr = prev_s[curr]
            path_s.reverse()

            path_t = []
            curr = i
            while curr != -1:
                path_t.append(curr)
                curr = prev_t[curr]
            path_t.reverse()

            # Combine paths
            full_path = path_s + path_t[1:]
            # Check if path from s to t is valid
