    from collections import defaultdict
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bidirectional Dijkstra
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        prev = [-1] * n

        while heap:
            d, u = heapq.heappop(heap)
            if u == end:
                break
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    prev[v] = u
                    heapq.heappush(heap, (dist[v], v))
        return dist, prev

    # Run Dijkstra from both s and t
    dist_s, _ = dijkstra(s, t)
    dist_t, _ = dijkstra(t, s)

    # Check if t is reachable from s
    if dist_s[t] == float('inf'):
        return -1

    # Find the meeting point with minimum total distance
    min_dist = float('inf')
    for i in range(n):
        if dist_s[i] + dist_t[i] < min_dist:
            min_dist = dist_s[i] + dist_t[i]

    return min_dist

