import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bucket-queue algorithm
    # Each bucket corresponds to a distance value
    # We use a dictionary to map distance values to nodes
    # We also maintain a priority queue of buckets

    # Initialize distances to infinity
    import math
    INF = math.inf
    dist = [INF] * n
    dist[s] = 0

    # Priority queue of buckets (distance, list of nodes)
    buckets = {}
    # Initially, all nodes are in the bucket corresponding to their distance
    for i in range(n):
        if dist[i] != INF:
            if dist[i] not in buckets:
                buckets[dist[i]] = []
            buckets[dist[i]].append(i)

    # Use a priority queue (min-heap) to get the bucket with the smallest distance
    heap = list(buckets.keys())
    heapq.heapify(heap)

    while heap:
        d = heapq.heappop(heap)
        if d not in buckets:
            continue
        # Process all nodes in this bucket
        for u in buckets[d]:
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    # Update distance
                    dist[v] = dist[u] + w
                    # Remove v from its current bucket
                    if dist[v] in buckets:
                        buckets[dist[v]].remove(v)
                    # Add v to the new bucket
                    if dist[v] not in buckets:
                        buckets[dist[v]] = []
                    buckets[dist[v]].append(v)
                    # Add the new bucket distance to the priority queue if not already present
                    if dist[v] not in heap:
                        heapq.heappush(heap, dist[v])

    return dist[t] if dist[t] != INF else -1

