from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bucket-queue implementation
    class Bucket:
        def __init__(self):
            self.elements = []

        def add(self, key):
            self.elements.append(key)

        def remove(self):
            if self.elements:
                return self.elements.pop()
            return None

        def is_empty(self):
            return len(self.elements) == 0

    # Initialize buckets for each distance
    # Bucket i contains nodes with current distance i
    max_distance = 100 * 100  # Since each edge has weight <= 100 and n <= 100
    buckets = [Bucket() for _ in range(max_distance + 1)]

    # Initialize distances to infinity
    dist = [float('inf')] * n
    dist[s] = 0
    buckets[0].add(s)

    # Priority queue for processing buckets in order
    pq = deque()
    pq.append(0)

    while pq:
        current_dist = pq.popleft()
        if buckets[current_dist].is_empty():
            continue

        node = buckets[current_dist].remove()
        for neighbor, weight in adj[node]:
            if dist[neighbor] > dist[node] + weight:
                dist[neighbor] = dist[node] + weight
                buckets[dist[neighbor]].add(neighbor)
                pq.append(dist[neighbor])

    return dist[t] if dist[t] != float('inf') else -1

