import heapq

def solve(grid, start, goal):
    if not grid or start == goal:
        # Check if start is a free cell
        if 0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.':
            return [start]
        else:
            return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Priority queue: (distance, row, col)
    heap = [(0, start[0], start[1])]
    # Visited keeps track of the shortest distance to each cell
    visited = {}
    # Parent map to reconstruct the path
    parent = {}

    while heap:
        dist, r, c = heapq.heappop(heap)
        if (r, c) == goal:
            # Reconstruct path
            path = []
            while (r, c) != start:
                path.append((r, c))
                r, c = parent[(r, c)]
            path.append(start)
            return path[::-1]

        if (r, c) in visited and visited[(r, c)] <= dist:
            continue

        visited[(r, c)] = dist
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                if (nr, nc) not in visited or visited[(nr, nc)] > dist + 1:
                    parent[(nr, nc)] = (r, c)
                    heapq.heappush(heap, (dist + 1, nr, nc))

    return []

