import heapq

def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if (
        start_row < 0 or start_row >= rows or
        start_col < 0 or start_col >= cols or
        grid[start_row][start_col] == '#' or
        grid[goal_row][goal_col] == '#'
    ):
        return []

    if start == goal:
        return [start]

    visited = set()
    heap = [(0, start_row, start_col)]
    came_from = {}

    while heap:
        dist, row, col = heapq.heappop(heap)
        if (row, col) == (goal_row, goal_col):
            break
        if (row, col) in visited:
            continue
        visited.add((row, col))

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_row, new_col = row + dr, col + dc
            if (
                0 <= new_row < rows and
                0 <= new_col < cols and
                grid[new_row][new_col] == '.' and
                (new_row, new_col) not in visited
            ):
                came_from[(new_row, new_col)] = (row, col)
                heapq.heappush(heap, (dist + 1, new_row, new_col))

    if (goal_row, goal_col) not in came_from:
        return []

    path = []
    current = (goal_row, goal_col)
    while current != start:
        path.append(current)
        current = came_from[current]
    path.append(start)
    return path[::-1]

