        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    visited = set()
    priority_queue = [(0, start)]
    parent = {}

    while priority_queue:
        dist, current = heapq.heappop(priority_queue)
        if current == goal:
