import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list for original graph
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Build adjacency list for reversed graph
    reversed_graph = [[] for _ in range(n)]
    for u, v, w in edges:
        reversed_graph[v].append((u, w))

    # Dijkstra's algorithm with priority queue
    def dijkstra(start, graph, target):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        visited = set()

        while heap:
            current_dist, u = heapq.heappop(heap)
            if u in visited:
                continue
            visited.add(u)
            if u == target:
                return current_dist
            for v, weight in graph[u]:
                if dist[v] > current_dist + weight:
                    dist[v] = current_dist + weight
                    heapq.heappush(heap, (dist[v], v))
        return float('inf')

    # Bidirectional Dijkstra
    forward_dist = dijkstra(s, graph, t)
    backward_dist = dijkstra(t, reversed_graph, s)

    if forward_dist == float('inf') or backward_dist == float('inf'):
        return -1
    else:
        return forward_dist

